'use strict';
const E=OpportunityEngine,KEY='pdl-opportunities-v2';let state=E.blank(),page='Overview',message='';
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(!E.validate(parsed).length)state=parsed;else message='Saved data is incompatible. A fresh workspace is ready.'}}catch{message='Storage unavailable or invalid. This session still works.'}
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tabs=['Overview','Product context','Ideas & evidence','Competitor matrix','Assessment & comparison','Decision Challenger','Criteria & capacity','Opportunity report'];
const opts={strength:[['unknown','Unknown'],['weak','Weak / stated interest'],['strong','Strong / behaviour or commitment']],expectation:[['unknown','Unknown'],['required','Required by target customers'],['optional','Optional'],['emerging','Emerging need']],unique:[['unknown','Unknown'],['yes','Distinct customer outcome'],['no','No — parity capability']],alternative:[['unknown','Unknown'],['available','Viable external option entered'],['unavailable','No viable external option identified']],evidenceType:[['user','User-provided / unverified'],['fictional','Fictional sample']],capability:[['unknown','Unknown'],['yes','Offers'],['partial','Partial'],['no','User reports absent']],action:[['','Not recorded'],...['Build Now','Validate First','Defer','Buy/Partner','Do Not Pursue'].map(x=>[x,x])]};
function field(label,path,value,{type='text',hint='',list=null}={}){return `<label class="field">${label}${list?`<select data-path="${path}">${list.map(([v,t])=>`<option value="${esc(v)}" ${String(value??'')===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select>`:type==='textarea'?`<textarea maxlength="10000" data-path="${path}">${esc(value)}</textarea>`:`<input data-path="${path}" type="${type}" ${type==='number'?'min="0" max="1000" step="any"':'maxlength="10000"'} value="${esc(value)}">`}${hint?`<small>${hint}</small>`:''}</label>`}
const check=(label,path,value)=>`<label class="check"><input type="checkbox" data-path="${path}" ${value?'checked':''}>${label}</label>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));message='Saved in this browser.'}catch{message='Storage unavailable. Keep this tab open or export a report.'}}
function go(name){page=name;render();$('#content').focus()}
function provenance(){return `<div class="notice">${state.sample?'<strong>Fictional Northstar Cloud scenario.</strong> Sample signals, evidence and competitor profiles are invented for demonstration.':'<strong>User-entered workspace.</strong> Evidence and competitor claims are manually supplied and not independently verified.'} Analysis uses transparent rules, not an LLM. No live research is performed.</div>`}
function overview(){return `<span class="eyebrow">PRODUCT DECISION LAB</span><h1>One idea or three.<br><em>Is it worth building?</em></h1><p class="lead">Evaluate opportunities using your context, customer evidence and manually supplied competitor information. Understand what to build, validate or leave behind.</p><div class="grid"><div class="card hero-card"><div class="icon">①</div><h2>Evaluate one idea</h2><p>Explore demand, competitive relevance, strategic fit and the next question to validate.</p><button class="primary" data-start="single">Evaluate one idea →</button></div><div class="card hero-card"><div class="icon">≋</div><h2>Compare 2–3 ideas</h2><p>Compare investments side by side. Adjust strategic priorities without forcing a winner.</p><button class="primary" data-start="compare">Compare ideas →</button></div></div><div class="card sample-banner"><div><h2>A familiar trade-off. A fictional company.</h2><p>Northstar Cloud: enterprise SSO, AI-powered insights or audit logging?</p></div><button data-sample>Try sample scenario ↗</button></div><div class="steps"><span>01 Set context</span><span>02 Enter ideas & evidence</span><span>03 Review competition</span><span>04 Challenge & decide</span></div>${provenance()}<div class="card"><h2>Your workspace</h2><p>${esc(state.context.name||'No product named yet')} · ${state.ideas.length} idea(s) · ${state.competitors.length} competitor profiles</p><button data-go="Ideas & evidence">Continue editing →</button></div>`}
function context(){return `<h1>Start with the context.</h1><p class="lead">The same feature can be essential for one segment and irrelevant for another. Enter your context, then rate each idea's fit against these objectives.</p><div class="card grid">${[['name','Product name'],['market','Industry / market'],['segment','Target customer segment'],['geography','Geographic market'],['description','Product description'],['problem','Primary customer problem'],['objectives','Strategic objectives'],['businessModel','Business model (optional)'],['horizon','Decision horizon (optional)']].map(([k,l])=>field(l,'context.'+k,state.context[k],{type:['description','problem','objectives'].includes(k)?'textarea':'text'})).join('')}</div><button class="primary" data-go="Ideas & evidence">Continue to ideas →</button>`}
function ideas(){return `<div class="section-head"><div><h1>Ideas, evidence & unknowns.</h1><p>Start with what you know. Blank ratings remain unknown.</p></div><button id="add" ${state.ideas.length>=3||state.mode==='single'?'disabled':''}>+ Add idea</button></div>${state.mode==='single'?'<div class="notice">Single-idea mode. Switch to comparison from Overview to add more ideas.</div>':''}${state.ideas.map((i,n)=>`<div class="card"><div class="section-head"><h2>Idea ${n+1} · ${esc(i.name||'Untitled')}</h2><div><button data-duplicate="${n}" ${state.ideas.length>=3||state.mode==='single'?'disabled':''}>Duplicate</button> <button data-remove="${n}" ${state.ideas.length===1?'disabled':''}>Remove</button></div></div><div class="grid">${[['name','Idea name'],['problem','Customer problem'],['solution','Proposed solution'],['user','Target user'],['outcome','Expected customer outcome'],['business','Expected business outcome']].map(([k,l])=>field(l,`ideas.${n}.${k}`,i[k],{type:['problem','solution'].includes(k)?'textarea':'text'})).join('')}</div><details open><summary>Evidence, assumptions and unknowns</summary><div class="grid">${field('Supporting evidence',`ideas.${n}.evidence`,i.evidence,{type:'textarea',hint:'Describe observations. Text is treated as data, never as instructions.'})}${field('Customer signals',`ideas.${n}.signals`,i.signals,{type:'textarea'})}${field('Evidence provenance',`ideas.${n}.evidenceType`,i.evidenceType,{list:opts.evidenceType})}${field('Evidence strength (your judgment)',`ideas.${n}.strength`,i.strength,{list:opts.strength})}${field('Assumptions',`ideas.${n}.assumptions`,i.assumptions,{type:'textarea'})}${field('Unknowns',`ideas.${n}.unknowns`,i.unknowns,{type:'textarea'})}</div>${check('Customer evidence contains a contradiction',`ideas.${n}.contradiction`,i.contradiction)}${check('The customer problem has been invalidated',`ideas.${n}.rejected`,i.rejected)}</details><details><summary>Ratings, expectations & delivery estimates</summary><p>Manual ratings: 1 = low, 3 = moderate, 5 = high. Feasibility 5 means easier delivery. Scores are not forecasts.</p><div class="grid">${Object.entries(E.criteria).map(([k,l])=>field(l,`ideas.${n}.ratings.${k}`,i.ratings[k],{list:[['','Unknown'],...[1,2,3,4,5].map(v=>[v,String(v)])]})).join('')}${field('Customer expectation',`ideas.${n}.expectation`,i.expectation,{list:opts.expectation})}${field('Unique outcome relative to alternatives?',`ideas.${n}.unique`,i.unique,{list:opts.unique})}${field('Build alternatives',`ideas.${n}.alternative`,i.alternative,{list:opts.alternative})}${field('Engineering effort (relative points)',`ideas.${n}.effort`,i.effort,{type:'number',hint:'Optional; unknown effort prevents a Build Now gate.'})}${field('Additive portfolio value (optional)',`ideas.${n}.portfolioValue`,i.portfolioValue,{type:'number',hint:'Comparable units across ideas; not a value/effort ratio.'})}</div>${check('Unresolved delivery blocker',`ideas.${n}.blocked`,i.blocked)}<h3>Dependencies — must also be selected</h3>${state.ideas.filter(x=>x.id!==i.id).map(x=>`<label class="check"><input type="checkbox" data-dependency="${n}" value="${x.id}" ${i.dependencies.includes(x.id)?'checked':''}>${esc(x.name||'Untitled')}</label>`).join('')||'<p>No other ideas to depend on.</p>'}</details></div>`).join('')}<div class="actions"><button class="primary" data-go="Competitor matrix">Review competitor capabilities →</button><button data-go="Assessment & comparison">Assess current inputs</button></div>`}
function competitors(){return `<div class="section-head"><div><h1>Competition in context.</h1><p>Included in both evaluation modes. Unknown is not absent.</p></div><button id="add-competitor" ${state.competitors.length>=10?'disabled':''}>+ Add competitor</button></div>${provenance()}${state.competitors.length?state.competitors.map((c,n)=>`<div class="card"><div class="section-head"><h2>${esc(c.name||'Unnamed profile')}</h2><button data-remove-competitor="${n}">Remove profile</button></div><div class="grid">${field('Competitor / substitute',`competitors.${n}.name`,c.name)}${field('Positioning / segment',`competitors.${n}.position`,c.position)}${field('Manual reference / source note',`competitors.${n}.source`,c.source,{hint:'Reference only. The app never fetches or verifies this text.'})}${field('Source date (optional)',`competitors.${n}.date`,c.date,{type:'date'})}${field('Provenance',`competitors.${n}.status`,c.status,{list:[['user','User-provided / unverified'],['fictional','Fictional sample']]})}</div><div class="grid3">${state.ideas.map(i=>field(i.name||'Untitled',`competitors.${n}.capabilities.${i.id}`,c.capabilities[i.id]||'unknown',{list:opts.capability})).join('')}</div></div>`).join(''):'<div class="card empty"><h2>No competitor information yet</h2><p>Add a manual profile or continue with competitive uncertainty disclosed.</p></div>'}<button class="primary" data-go="Assessment & comparison">See the assessment →</button>`}
function comparison(){const r=E.evaluate(state);return `<h1>${state.ideas.length===1?'Your opportunity assessment.':'Compare the investment choices.'}</h1><p class="lead">${r.summary}</p>${provenance()}<div class="grid3">${state.ideas.map(i=>{const a=r.assessments.find(a=>a.id===i.id);return `<div class="card"><span class="pill-label">${esc(i.name||'Untitled')}</span><div class="decision">${a.action}</div><p>${a.reason}</p><div class="score">${a.score??'—'} <small>${a.complete?' / 100':'Incomplete assessment'}</small></div><p class="muted">${a.coverage}% of active weight rated${a.score===null&&a.partialScore!==null?`; provisional ${a.partialScore}/100 on known ratings only`:''}</p><div class="bar"><span style="width:${a.coverage}%"></span></div><p>${a.comp.tags.map(t=>`<span class="badge">${t}</span>`).join('')}</p><details open><summary>Why these classifications?</summary><ul>${a.comp.why.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details><details><summary>Evidence and missing information</summary><p>${a.confidence} · ${esc(i.evidence||'No evidence entered')}</p><ul>${a.gaps.map(t=>`<li>Missing / unknown: ${t}</li>`).join('')}</ul></details><details><summary>Counterargument & next step</summary><p>${a.counterargument}</p><p>${esc(a.challenges[0])}</p><p>${esc(a.change)}</p></details></div>`}).join('')}</div><div class="card table-wrap"><h2>Side-by-side inputs</h2><table><thead><tr><th>Dimension</th>${state.ideas.map(i=>`<th>${esc(i.name||'Untitled')}</th>`).join('')}</tr></thead><tbody>${[...Object.entries(E.criteria).map(([k,l])=>[l,i=>i.ratings[k]===null?'Unknown':i.ratings[k]+'/5']),['Evidence',i=>i.strength],['Effort',i=>i.effort??'Unknown'],['Unique outcome',i=>i.unique],['External option',i=>i.alternative],['Risks / unknowns',i=>i.unknowns||'Not recorded']].map(([label,fn])=>`<tr><th>${label}</th>${state.ideas.map(i=>`<td>${esc(fn(i))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="actions"><button data-go="Criteria & capacity">Adjust criteria</button><button class="primary" data-go="Decision Challenger">Challenge assessment →</button></div>`}
function challenger(){const r=E.evaluate(state);return `<h1>Challenge the recommendation.</h1><p class="lead">Context-aware rules, not model output. Edit the inputs, question the recommendation, or record your own judgment.</p>${r.assessments.map((a,n)=>`<div class="card"><div class="section-head"><h2>${esc(state.ideas[n].name||'Untitled')}</h2><span class="tag">${a.action}</span></div>${a.challenges.map(c=>`<div class="rule">${esc(c)}</div>`).join('')}<h3>What would change this recommendation?</h3><p>${esc(a.change)}</p><div class="grid">${field('PM final decision — may differ from the rules',`ideas.${n}.decision`,state.ideas[n].decision,{list:opts.action})}${field('Your rationale / rejected conclusion',`ideas.${n}.notes`,state.ideas[n].notes,{type:'textarea'})}</div></div>`).join('')}<button class="primary" data-go="Opportunity report">Generate Opportunity Assessment →</button>`}
function criteria(){const p=E.portfolio(state),selected=state.ideas.filter(i=>state.selected.includes(i.id)),unknown=selected.some(i=>i.effort===null),used=selected.reduce((n,i)=>n+(i.effort||0),0),deps=selected.some(i=>i.dependencies.some(id=>!state.selected.includes(id)));return `<h1>Make the trade-offs explicit.</h1><div class="grid"><div class="card"><h2>Decision criteria</h2><p>Weighted score = Σ(rating ÷ 5 × weight) ÷ Σ(active weights) × 100. Weights normalise automatically. Zero excludes a criterion. Unknown ratings give a provisional score only.</p>${Object.entries(E.criteria).map(([k,l])=>field(l+' weight',`weights.${k}`,state.weights[k],{type:'number',hint:'0–100'})).join('')}<details open><summary>Recommendation gates</summary><p>Invalidated problem → Do Not Pursue. Contradiction or missing mandatory inputs → Validate First. With strong evidence and complete ratings: low problem and strategy → Do Not Pursue; blocker or low strategy → Defer; required parity with a viable external option and no unique outcome → Buy/Partner; score ≥70 with problem, strategy and feasibility ≥3 → Build Now. Score &lt;45 → Defer. Otherwise → Validate First. Competitor uncertainty is disclosed separately.</p></details></div><div class="card"><h2>Optional capacity stage</h2><p>Compare additive entered value, not priority ratios. This optimiser is not an investment recommendation. Review the opportunity assessment first.</p>${field('Engineering capacity','capacity',state.capacity,{type:'number'})}${state.ideas.map(i=>`<label class="check"><input type="checkbox" data-select="${i.id}" ${state.selected.includes(i.id)?'checked':''}>${esc(i.name||'Untitled')} · effort ${i.effort??'unknown'} · value ${i.portfolioValue??'unknown'}</label>`).join('')}<div class="notice ${unknown||used>state.capacity||deps?'warning':''}">${unknown?'Selected effort is unknown.':`Selected effort ${used}/${state.capacity}. ${used>state.capacity?'Over capacity.':'Within capacity.'}`} ${deps?'A required dependency is missing.':''}</div><h3>Highest additive value that fits</h3><p>${p.ids.map(id=>esc(state.ideas.find(i=>i.id===id).name||'Untitled')).join(' + ')||'No positive-value feasible portfolio.'}</p><p>${p.effort} effort · ${p.value} entered value units</p><p class="muted">Unknown effort/value and blocked or invalidated ideas are excluded. Dependencies must be selected together. Additive value assumes no overlap or synergy.</p><button id="apply-portfolio">Apply portfolio selection</button> <button id="snapshot">Save scenario</button><details><summary>Saved scenarios (${state.snapshots.length})</summary>${state.snapshots.map(s=>`<p>${esc(s.names)} · ${s.effort??'Unknown'} / ${s.capacity} points · ${esc(s.date)}</p>`).join('')||'<p>No saved scenarios.</p>'}</details></div></div><button class="primary" data-go="Assessment & comparison">Review updated assessment →</button>`}
function reportView(){return `<h1>A decision worth explaining.</h1><p class="lead">Context, evidence, competitive assumptions and your final judgment in one reviewable document.</p><div class="actions"><button id="copy" class="primary">Copy Markdown</button><button id="download">Download .md ↓</button><button data-go="Decision Challenger">Edit PM decision</button></div><div class="card"><label class="field">Opportunity Assessment<textarea class="report" readonly>${esc(E.report(state))}</textarea></label></div>`}
function render(){const errors=E.validate(state);if(errors.length){$('#view').innerHTML=`<div class="notice warning">${esc(errors.join('; '))}</div>`;return}$('#nav').innerHTML=tabs.map(t=>`<button data-go="${t}" class="${page===t?'active':''}" ${page===t?'aria-current="page"':''}>${t}</button>`).join('');$('#status').textContent=message;$('#view').innerHTML=({'Overview':overview,'Product context':context,'Ideas & evidence':ideas,'Competitor matrix':competitors,'Assessment & comparison':comparison,'Decision Challenger':challenger,'Criteria & capacity':criteria,'Opportunity report':reportView}[page])();bind()}
function setPath(path,value){const parts=path.split('.');let target=state;for(const k of parts.slice(0,-1))target=target[k];target[parts.at(-1)]=value}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-path]').forEach(el=>el.onchange=()=>{const path=el.dataset.path;let value=el.type==='checkbox'?el.checked:el.value;if(el.type==='number'){if(!el.checkValidity()){el.reportValidity();return}value=el.value===''?null:Number(el.value);if(path.startsWith('weights.'))value=Math.min(100,Math.max(0,value??0));if(path==='capacity')value=value??0}if(path.includes('.ratings.'))value=value===''?null:Number(value);setPath(path,value);save();$('#status').textContent=message;if(!['Product context','Ideas & evidence','Competitor matrix','Decision Challenger'].includes(page))render()});document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=loadSample);document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{if(b.dataset.start==='single'&&state.ideas.length>1){confirmReplace('Start a fresh single-idea workspace?',()=>{state=E.blank();save();go('Product context')});return}state.mode=b.dataset.start;if(state.mode==='compare'&&state.ideas.length===1)state.ideas.push(E.blankIdea('idea-'+Date.now()));save();go('Product context')});if($('#add'))$('#add').onclick=()=>{state.ideas.push(E.blankIdea('idea-'+Date.now()));save();render()};document.querySelectorAll('[data-duplicate]').forEach(b=>b.onclick=()=>{const i=structuredClone(state.ideas[Number(b.dataset.duplicate)]);i.id='idea-'+Date.now();i.name+=' (copy)';i.dependencies=[];state.ideas.push(i);save();render()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const [i]=state.ideas.splice(Number(b.dataset.remove),1);state.ideas.forEach(x=>x.dependencies=x.dependencies.filter(id=>id!==i.id));state.selected=state.selected.filter(id=>id!==i.id);state.competitors.forEach(c=>delete c.capabilities[i.id]);save();render()});document.querySelectorAll('[data-dependency]').forEach(el=>el.onchange=()=>{const i=state.ideas[Number(el.dataset.dependency)];i.dependencies=el.checked?[...i.dependencies,el.value]:i.dependencies.filter(id=>id!==el.value);save()});if($('#add-competitor'))$('#add-competitor').onclick=()=>{state.competitors.push({id:'c-'+Date.now(),name:'',position:'',source:'',date:'',status:'user',capabilities:{}});save();render()};document.querySelectorAll('[data-remove-competitor]').forEach(b=>b.onclick=()=>{state.competitors.splice(Number(b.dataset.removeCompetitor),1);save();render()});document.querySelectorAll('[data-select]').forEach(el=>el.onchange=()=>{state.selected=el.checked?[...state.selected,el.dataset.select]:state.selected.filter(id=>id!==el.dataset.select);save();render()});if($('#apply-portfolio'))$('#apply-portfolio').onclick=()=>{state.selected=E.portfolio(state).ids;save();render()};if($('#snapshot'))$('#snapshot').onclick=()=>{const chosen=state.ideas.filter(i=>state.selected.includes(i.id));state.snapshots.unshift({names:chosen.map(i=>i.name||'Untitled').join(' + ')||'Empty portfolio',capacity:state.capacity,effort:chosen.some(i=>i.effort===null)?null:chosen.reduce((n,i)=>n+i.effort,0),date:new Date().toLocaleString()});state.snapshots=state.snapshots.slice(0,10);save();render()};if($('#copy'))$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(E.report(state));$('#status').textContent='Report copied.'}catch{$('#status').textContent='Clipboard unavailable. Select the report text or download Markdown.'}};if($('#download'))$('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([E.report(state)],{type:'text/markdown'}));const a=document.createElement('a');a.href=url;a.download='opportunity-assessment.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
function confirmReplace(title,action){$('#confirm-title').textContent=title;$('#confirm-action').onclick=()=>{$('#confirm').close();action()};$('#confirm').showModal()}
function loadSample(){confirmReplace('Load fictional Northstar Cloud sample?',()=>{state=E.sample();save();go('Ideas & evidence')})}
$('#cancel').onclick=()=>$('#confirm').close();$('#sample').onclick=loadSample;$('#reset').onclick=()=>confirmReplace('Reset to a fresh workspace?',()=>{state=E.blank();save();go('Overview')});$('#clear').onclick=()=>confirmReplace('Clear all saved V2 data?',()=>{state=E.blank();try{localStorage.removeItem(KEY);message='V2 data cleared from this browser.'}catch{message='Could not access browser storage.'}go('Overview')});render();
